def time_due(now, deadline):
    """Compare decision deadlines using P's existing absolute event-time tolerance.

    This only classifies a controller boundary; it never modifies world time.
    """
    return now>=deadline or math.isclose(now,deadline,rel_tol=0.,abs_tol=Config().event_time_tol)
